catalog_script_client.script:
function onLoad() {
    aplicarMascaraPercentual('v_valor_apurado_endividamento');
    aplicarMascaraPercentual('v_meta_endividamento');
    aplicarMascaraPercentual('v_valor_apurado_despesa_com_pessoal');
    aplicarMascaraPercentual('v_meta_despesa_com_pessoal');

}

function aplicarMascaraPercentual(variableName) {
    var field = g_form.getControl(variableName);
    if (!field) return;

    var rawValue = '';

    field.addEventListener('input', function () {
        rawValue = this.value.replace(/\D/g, '');

        if (rawValue === '') {
            this.value = '';
            return;
        }

        var number = parseFloat(rawValue) / 100;

        this.value = number.toLocaleString('pt-BR', {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2
        }) + '%';
    });
}
